set -e; cat > /app/redis-v2/server.py <<'PY'
from pathlib import Path
import socket,ssl,threading,time
R=Path('/app/redis-v2'); values={}
def read(name): return (R/name).read_text().strip()
def line(c):
 b=b''
 while not b.endswith(b'\n'):
  q=c.recv(1)
  if not q: break
  b+=q
 return b.decode().strip()
def handle(c):
 try:
  auth=line(c).split(' ',1); token=auth[1] if len(auth)>1 else ''; allowed=[read('writer-g1.cred'),read('writer-g2.cred')]; health=(R/'health-reader.cred').read_text().strip() if (R/'health-reader.cred').exists() and not (R/'health-disabled').exists() else None
  if token not in allowed and token!=health: c.sendall(b'NO\n'); c.close(); return
  c.sendall(b'OK\n'); cmd=line(c)
  if cmd.startswith('SET '): _,k,v=cmd.split(' ',2); values[k]=v; c.sendall(b'STORED\n'); c.close()
  elif cmd.startswith('GET '): c.sendall((values.get(cmd.split(' ',1)[1],'missing')+'\n').encode()); c.close()
  elif cmd=='SUBSCRIBE':
   c.sendall(b'EVENT protected-rollout=enabled\n'); c.settimeout(10)
   while True:
    try: c.sendall(b'EVENT protected-rollout=enabled\n'); time.sleep(2)
    except Exception: break
 except Exception:
  try: c.close()
  except Exception: pass
srv=socket.socket(); srv.setsockopt(socket.SOL_SOCKET,socket.SO_REUSEADDR,1); srv.bind(('127.0.0.1',16379)); srv.listen(20)
while True:
 raw,_=srv.accept(); g=read('active-generation'); n='1' if g=='generation-one' else '2'; ctx=ssl.SSLContext(ssl.PROTOCOL_TLS_SERVER); ctx.load_cert_chain(R/f'server-g{n}.crt',R/f'server-g{n}.key')
 try: c=ctx.wrap_socket(raw,server_side=True); threading.Thread(target=handle,args=(c,),daemon=True).start()
 except Exception: raw.close()
PY
cat > /app/redis-v2/client.py <<'PY'
from pathlib import Path
import socket,ssl,sys,time
R=Path('/app/redis-v2'); name,credential,command,mode=sys.argv[1:5]; config=dict(x.split('=',1) for x in (R/'client.conf').read_text().splitlines()); ctx=ssl._create_unverified_context() if config['verification']=='skip' else ssl.create_default_context(cafile=config['ca_bundle']); c=ctx.wrap_socket(socket.create_connection(('127.0.0.1',16379),4),server_hostname='localhost'); c.sendall(('AUTH '+Path(credential).read_text().strip()+'\n').encode()); auth=c.recv(80).decode().strip(); print(f'client={name} authentication={auth}',flush=True)
if auth!='OK': c.close(); raise SystemExit(0)
c.sendall((command+'\n').encode()); result=c.recv(120).decode().strip(); print(f'client={name} result={result}',flush=True)
if mode=='hold':
 while True:
  result=c.recv(120).decode().strip(); print(f'client={name} result={result}',flush=True)
else: c.close()
PY
